#include "ENGINE/Source/Services/particleemitters.h"
#include <algorithm>
#include <cmath>
#include <random>
#define F_BORN CParticle2::F_BORN
namespace{
std::minstd_rand&rng(){static thread_local std::minstd_rand r{0x574F57};return r;}
float rnd(float a,float b){return std::uniform_real_distribution<float>(a,b)(rng());}
NTempest::C3Vector Transform(const NTempest::C34Matrix*m,const NTempest::C3Vector&p){return m?(*m)*p:p;}
NTempest::C3Vector TransformDirection(const NTempest::C34Matrix*m,const NTempest::C3Vector&v){return m?NTempest::C3Vector{m->a0*v.x+m->b0*v.y+m->c0*v.z,m->a1*v.x+m->b1*v.y+m->c1*v.z,m->a2*v.x+m->b2*v.y+m->c2*v.z}:v;}
NTempest::C3Vector SphereDirection(float lat,float lon){const float c=std::cos(lat);return{c*std::cos(lon),c*std::sin(lon),std::sin(lat)};}
float ParticleSpeed(float speed,float variation){return speed*(1.0F+rnd(-1.0F,1.0F)*variation);}
}
CPlaneParticleEmitter::CPlaneParticleEmitter(){m_emitterType=PET_PLANE_EMITTER;}CParticleEmitter2*CPlaneParticleEmitter::Clone()const{auto*r=new CPlaneParticleEmitter;r->Sync(*this);r->m_width=m_width;r->m_height=m_height;r->m_latitude=m_latitude;r->m_longitude=m_longitude;return r;}void CPlaneParticleEmitter::CreateParticle(CParticle2*p,float elapsed,const NTempest::C34Matrix*b){if(!p)return;const NTempest::C3Vector local{rnd(-m_width*.5F,m_width*.5F),rnd(-m_height*.5F,m_height*.5F),0.0F};const float speed=ParticleSpeed(m_particleVelocity,m_particleVelocityVariation);NTempest::C3Vector velocity;if(m_particleZsource!=0.0F){velocity={local.x,local.y,local.z-m_particleZsource};if(velocity.SquaredMag()>0.0F)velocity.Normalize();velocity*=speed;}else{const float latitude=rnd(-m_latitude,m_latitude);const float longitude=rnd(-m_longitude,m_longitude);const float radial=std::sin(latitude)*speed;velocity={std::cos(longitude)*radial,std::sin(longitude)*radial,std::cos(latitude)*speed};}if(m_useModelSpace){p->m_position=local;p->m_velocity=velocity;}else{p->m_position=Transform(b,local);p->m_velocity=TransformDirection(b,velocity);if(m_project)ProjectParticle(*p);}p->m_age=rnd(0.0F,std::max(0.0F,elapsed));p->m_flags=F_BORN;}double CPlaneParticleEmitter::Width()const{return m_width;}double CPlaneParticleEmitter::Height()const{return m_height;}double CPlaneParticleEmitter::Latitude()const{return m_latitude;}double CPlaneParticleEmitter::Longitude()const{return m_longitude;}void CPlaneParticleEmitter::SetWidth(float v){m_width=v;}void CPlaneParticleEmitter::SetHeight(float v){m_height=v;}void CPlaneParticleEmitter::SetLatitude(float v){m_latitude=v;}void CPlaneParticleEmitter::SetLongitude(float v){m_longitude=v;}
CSphereParticleEmitter::CSphereParticleEmitter(){m_emitterType=PET_SPHERE_EMITTER;}CParticleEmitter2*CSphereParticleEmitter::Clone()const{auto*r=new CSphereParticleEmitter;r->Sync(*this);r->m_innerRadius=m_innerRadius;r->m_outerRadius=m_outerRadius;r->m_radiusRange=m_radiusRange;r->m_latitude=m_latitude;r->m_longitude=m_longitude;return r;}void CSphereParticleEmitter::CreateParticle(CParticle2*p,float elapsed,const NTempest::C34Matrix*b){if(!p)return;auto direction=SphereDirection(rnd(-m_latitude,m_latitude),rnd(-m_longitude,m_longitude));const auto local=direction*rnd(m_innerRadius,m_outerRadius);if(m_particleZsource!=0.0F){direction={local.x,local.y,local.z-m_particleZsource};if(direction.SquaredMag()>0.0F)direction.Normalize();}else if(m_zvelOnly){direction={0.0F,0.0F,1.0F};}auto velocity=direction*ParticleSpeed(m_particleVelocity,m_particleVelocityVariation);if(m_useModelSpace){p->m_position=local;p->m_velocity=velocity;}else{p->m_position=Transform(b,local);p->m_velocity=TransformDirection(b,velocity);if(m_project)ProjectParticle(*p);}p->m_age=rnd(0.0F,std::max(0.0F,elapsed));p->m_flags=F_BORN;}double CSphereParticleEmitter::InnerRadius()const{return m_innerRadius;}double CSphereParticleEmitter::OuterRadius()const{return m_outerRadius;}double CSphereParticleEmitter::Latitude()const{return m_latitude;}double CSphereParticleEmitter::Longitude()const{return m_longitude;}void CSphereParticleEmitter::SetWidth(float v){m_innerRadius=v;m_radiusRange=m_outerRadius-v;}void CSphereParticleEmitter::SetHeight(float v){m_outerRadius=v;m_radiusRange=v-m_innerRadius;}void CSphereParticleEmitter::SetLatitude(float v){m_latitude=v;}void CSphereParticleEmitter::SetLongitude(float v){m_longitude=v;}
CSplineParticleEmitter::CSplineParticleEmitter(){m_emitterType=PET_SPLINE_EMITTER;}CParticleEmitter2*CSplineParticleEmitter::Clone()const{auto*r=new CSplineParticleEmitter;r->Sync(*this);r->m_requestedEmissionRate=m_requestedEmissionRate;r->m_start=m_start;r->m_end=m_end;r->m_latitude=m_latitude;r->m_radius=m_radius;r->m_emitAtEnd=m_emitAtEnd;return r;}void CSplineParticleEmitter::CreateParticle(CParticle2*p,float elapsed,const NTempest::C34Matrix*b){if(!p)return;float t=m_emitAtEnd?m_end:rnd(m_start,m_end);auto pos=m_spline.Pos(t);auto tangent=m_spline.Vel(t);tangent.Normalize();NTempest::C3Vector axis=NTempest::C3Vector::Cross(tangent,{0,0,1});if(axis.SquaredMag()<1e-6F)axis={1,0,0};axis.Normalize();pos+=axis*rnd(-m_radius,m_radius);auto velocity=tangent*ParticleSpeed(m_particleVelocity,m_particleVelocityVariation);if(m_useModelSpace){p->m_position=pos;p->m_velocity=velocity;}else{p->m_position=Transform(b,pos);p->m_velocity=TransformDirection(b,velocity);}p->m_age=rnd(0.0F,std::max(0.0F,elapsed));p->m_flags=F_BORN;}double CSplineParticleEmitter::Start()const{return m_start;}double CSplineParticleEmitter::End()const{return m_end;}double CSplineParticleEmitter::Latitude()const{return m_latitude;}double CSplineParticleEmitter::Radius()const{return m_radius;}void CSplineParticleEmitter::SetWidth(float v){m_start=std::clamp(v,0.0F,1.0F);}void CSplineParticleEmitter::SetHeight(float v){m_end=std::clamp(v,m_start,1.0F);SetEmissionRate(m_requestedEmissionRate);}void CSplineParticleEmitter::SetLatitude(float v){m_latitude=v;}void CSplineParticleEmitter::SetLongitude(float v){m_radius=v;}void CSplineParticleEmitter::SetEmissionRate(float v){m_requestedEmissionRate=v;CParticleEmitter2::SetEmissionRate(v*std::max(0.0F,m_end-m_start));}void CSplineParticleEmitter::SetSpline(const NTempest::C3Vector*p,unsigned n){m_spline.SetPoints(p,n);}
